from abc import ABC, abstractmethod
from typing import Optional

from app.models.schemas import AgentState, TaskRequirement


class BaseAgent(ABC):
    """Base class for all financial decision-support agents."""

    def __init__(
        self,
        name: str,
        reliability: float,
        estimated_cost: int,
    ) -> None:
        self.name = name
        self.reliability = reliability
        self.estimated_cost = estimated_cost

        # Stores the structured task information generated by
        # the query analyzer.
        self.task_requirement: Optional[TaskRequirement] = None

    def set_task_requirement(
        self,
        requirement: TaskRequirement,
    ) -> None:
        """
        Attach the structured task requirement to the agent.

        The Executor calls this before execution.

        This allows agents to access:
            - query
            - required_capabilities
            - risk_preference
            - initial_amount
            - target_amount
            - years
            - annual_return
            - symbols

        without immediately changing every agent's execute()
        method signature.
        """
        self.task_requirement = requirement

    def get_task_requirement(self) -> TaskRequirement:
        """
        Return the task requirement attached to this agent.

        Raises:
            RuntimeError: if the agent is executed without
            receiving a task requirement.
        """

        if self.task_requirement is None:
            raise RuntimeError(
                f"No TaskRequirement has been assigned to {self.name}."
            )

        return self.task_requirement

    @abstractmethod
    def execute(
        self,
        query: str,
        budget: int,
    ) -> AgentState:
        """
        Execute the agent's task.

        Concrete agents must implement this method.
        """
        raise NotImplementedError